; Applying a function value, and the tag trap.
;
; ap_N (N = 1-9, generated by build.py): r6 = a function value (perhaps
; not evaluated), its N arguments in r1-r5, r0, r8-r10, r7 = the return.
; The fast case, a function of arity N, jumps to its entry; anything else
; comes here, with r12 = N.
;
; ap_slow works on a frame of the registers on the stack, where the
; collector can see them, the dead ones cleared:
;   [sp] = 4N, [sp + 4] = 4 * the function's arity, [sp + 8 + 4j] = rj (j = 0-10)
FR_N    = 0
FR_A    = 4
FR_R6   = 8 + 4 * 6
FR_R7   = 8 + 4 * 7
FR_SIZE = 8 + 4 * 11

ap_slow:
        SAVE r0-r10
        CLR  -[sp]
        LSL  r12, #2
        MOV  -[sp], r12
        ; clear the slots of the argument registers past N
        MOV  r1, r12
        LSR  r1, #2
.clr:   CMP  r1, #9
        BHS  .disp
        MOV  r2, byte [argslot + r1]
        ADD  r2, sp
        CLR  [r2]
        INC  r1
        BRA  .clr
.disp:  MOV  r6, [sp + FR_R6]
        TST  r6, #1
        BEQ  .evald
        CALL [r6 - 1]
        MOV  [sp + FR_R6], r1
        MOV  r6, r1
.evald: MOV  r12, [r6 - 2]
        CMP  r12, #pap_entry + 1
        BEQ  .pap
        MOV  r2, byte [r12 - 6]     ; the arity
        LSL  r2, #2
        MOV  [sp + FR_A], r2
        MOV  r1, [sp + FR_N]
        CMP  r2, r1
        BEQ  .exact
        BHI  .partial
        ; too many arguments: call with the arity's first, then apply the
        ; result to the rest
        LEA  r12, [sp + 8]
        LDM  r12, r0-r10
        CALL [r6 - 2]
        MOV  [sp + FR_R6], r1
        MOV  r3, [sp + FR_A]        ; 4a
        LSR  r3, #2
        MOV  r4, [sp + FR_N]
        LSR  r4, #2
        SUB  r4, r3                 ; the rest: N - a
        CLR  r1                     ; i
.down:  CMP  r1, r4
        BHS  .downz
        MOV  r2, r1
        ADD  r2, r3
        MOV  r2, byte [argslot + r2]
        ADD  r2, sp
        MOV  r5, [r2]               ; argument a + i
        MOV  r2, byte [argslot + r1]
        ADD  r2, sp
        MOV  [r2], r5               ; into argument i
        INC  r1
        BRA  .down
.downz: MOV  r2, r4                 ; clear arguments N - a .. N - 1
        ADD  r2, r3
.dclr:  CMP  r1, r2
        BHS  .dnew
        MOV  r5, byte [argslot + r1]
        ADD  r5, sp
        CLR  [r5]
        INC  r1
        BRA  .dclr
.dnew:  LSL  r4, #2
        MOV  [sp + FR_N], r4
        BRA  .disp
.exact: ADD  sp, #8
        RESTORE r0-r10
        JMP  [r6 - 2]
        ; a partial application: put the arguments after the PAP's own
.pap:   MOV  r3, [r6 + 6]           ; 4k
        LSR  r3, #2
        MOV  r4, [sp + FR_N]
        LSR  r4, #2
        MOV  r1, r4
        ADD  r1, r3
        CMP  r1, #9
        BHI  rt_toomany
        MOV  r1, r4                 ; i = N - 1 down to 0: argument i -> i + k
.up:    TST  r1, r1
        BEQ  .upz
        DEC  r1
        MOV  r2, byte [argslot + r1]
        ADD  r2, sp
        MOV  r5, [r2]
        MOV  r2, r1
        ADD  r2, r3
        MOV  r2, byte [argslot + r2]
        ADD  r2, sp
        MOV  [r2], r5
        BRA  .up
.upz:   CMP  r1, r3                 ; i = 0 .. k - 1: the PAP's arguments
        BHS  .upf
        MOV  r2, r1
        LSL  r2, #2
        ADD  r2, r6
        MOV  r5, [r2 + 10]
        MOV  r2, byte [argslot + r1]
        ADD  r2, sp
        MOV  [r2], r5
        INC  r1
        BRA  .upz
.upf:   MOV  r5, [r6 + 2]           ; the PAP's function
        MOV  [sp + FR_R6], r5
        ADD  r4, r3
        LSL  r4, #2
        MOV  [sp + FR_N], r4
        BRA  .disp
        ; fewer arguments than the arity: make a partial application
.partial:
        CMP  r14, r13
        BHI  .gc
        MOV  r12, #pap_entry + 1
        MOV  [r14], r12
        MOV  [r14 + 4], r6
        MOV  r4, [sp + FR_N]
        MOV  [r14 + 8], r4
        LSR  r4, #2
        CLR  r1
.pcopy: CMP  r1, r4
        BHS  .pdone
        MOV  r2, byte [argslot + r1]
        ADD  r2, sp
        MOV  r5, [r2]
        MOV  r2, r1
        LSL  r2, #2
        ADD  r2, r14
        MOV  [r2 + 12], r5
        INC  r1
        BRA  .pcopy
.pdone: LEA  r1, [r14 + 2]
        LSL  r4, #2
        ADD  r4, #12
        ADD  r14, r4
        MOV  r7, [sp + FR_R7]
        ADD  sp, #FR_SIZE
        RET
.gc:    MOV  r12, #48
        CALL rt_gc
        MOV  r6, [sp + FR_R6]
        BRA  .partial

; the frame offsets of argument registers 0-8 (r1-r5, r0, r8-r10)
argslot:
        .byte 8 + 4, 8 + 8, 8 + 12, 8 + 16, 8 + 20, 8 + 0, 8 + 32, 8 + 36, 8 + 40
        .align 2

; ---- the tag trap: a TMOV found bit 0 set (a value not yet evaluated),
; or TADD, TSUB or TCMP overflowed. The stack has the flags, then the
; instruction's address. A TMOV is a check the code generator made: the
; trap jumps to that check's own slow path (found in trap_hash, which
; boot fills from trap_table), which evaluates the value, knowing what
; is live there, and returns with RTI to run the check again. Anything
; else is an overflow.
trap_tag:
        MOV  -[sp], r1
        MOV  -[sp], r2
        MOV  r1, [sp + 12]          ; the instruction
        MOV  r2, r1
        LSR  r2, #1
        AND  r2, #TRAP_HASH_SIZE - 1
        LSL  r2, #3
.probe: MOV  r12, [trap_hash + r2]
        CMP  r12, r1
        BEQ  .found
        TST  r12, r12
        BEQ  .over
        ADD  r2, #8
        AND  r2, #TRAP_HASH_SIZE * 8 - 1
        BRA  .probe
.found: MOV  r12, [trap_hash + 4 + r2]
        INC  [tag_traps]
        MOV  r2, [sp]+
        MOV  r1, [sp]+
        JMP  r12
.over:  JMP  rt_overflow

; trap_hash_init: fill trap_hash from trap_table, (check, slow path) pairs.
trap_hash_init:
        MOV  r3, #trap_table
.next:  CMP  r3, #trap_table_end
        BHS  .done
        MOV  r1, [r3]
        MOV  r2, r1
        LSR  r2, #1
        AND  r2, #TRAP_HASH_SIZE - 1
        LSL  r2, #3
.probe: MOV  r12, [trap_hash + r2]
        TST  r12, r12
        BEQ  .put
        ADD  r2, #8
        AND  r2, #TRAP_HASH_SIZE * 8 - 1
        BRA  .probe
.put:   MOV  [trap_hash + r2], r1
        MOV  r12, [r3 + 4]
        MOV  [trap_hash + 4 + r2], r12
        ADD  r3, #8
        BRA  .next
.done:  RET
